/// @title This module is to enter the market
module protocol::enter_market;

use std::type_name::{Self, TypeName};
use sui::event::emit;

use protocol::market::Market;
use protocol::obligation;
use protocol::app::PackageCallerCap;
use protocol::market::lending_default_emode_group;
use protocol::app::ProtocolApp;

public struct ObligationCreatedEvent has copy, drop {
    sender: address,
    market_type: TypeName,
    obligation: ID,
    emode_group: u8,
    obligation_admin_cap: ID,
}

/// @notice Create a new obligation and transfer the obligation owner cap to the sender
/// @dev the obaligation object will be a shared object, object key is the proof of ownership for the obligation
/// @param version The version control object, contract version must match with this
/// @param ctx The SUI transaction context object
#[allow(lint(self_transfer))]
public fun enter_market<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, ctx: &mut TxContext) {
    let obligation_cap = enter_market_return<MarketType>(app, market, ctx);
    transfer::public_transfer(obligation_cap, ctx.sender());
}

public fun enter_market_return<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    enter_market_inner<MarketType>(app, market, lending_default_emode_group(), ctx)
}

/// Being restrictive on who can join with emode. Consider lifting this restriction in future releases.
public fun enter_market_with_emode<MarketType>(app: &ProtocolApp, cap: &PackageCallerCap, market: &mut Market<MarketType>, emode_group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::enter_market_with_emode());
    enter_market_inner<MarketType>(app, market, emode_group, ctx)
}

fun enter_market_inner<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, emode_group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    market.assert_emode_group_exists(emode_group);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let market_type = type_name::with_defining_ids<MarketType>();
    let (obligation, obligation_cap) = obligation::new(object::id(market), emode_group, ctx);

    let obligation_id = obligation_cap.id();

    market.handle_new_obligation(obligation);

    // Emit the obligation created event
    emit(ObligationCreatedEvent {
        sender: ctx.sender(),
        market_type,
        emode_group,
        obligation: obligation_id,
        obligation_admin_cap: object::id(&obligation_cap),
    });

    obligation_cap
}

#[test_only]
public fun create_obligation_with_group<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    enter_market_inner<MarketType>(app, market, group, ctx)
}

